// src/lib.rs（示例代码）
use std::{
    sync::{Arc, Condvar, Mutex},
    time::Duration,
};

struct Inner<T> {
    val: Option<T>,
}

pub struct Sender<T>(Arc<(Mutex<Inner<T>>, Condvar)>);
pub struct Receiver<T>(Arc<(Mutex<Inner<T>>, Condvar)>);

pub fn channel<T>() -> (Sender<T>, Receiver<T>) {
    let shared = Arc::new((Mutex::new(Inner { val: None }), Condvar::new()));
    (Sender(shared.clone()), Receiver(shared))
}

impl<T> Sender<T> {
    /// 消费 self：语义与 job.rs 的 Sender::send 一致——只能发送一次。
    pub fn send(self, val: T) {
        let mut guard = self.0.lock.0.lock().unwrap();
        guard.val = Some(val);
        drop(guard);
        self.0.1.notify_all();
    }
}

impl<T> Receiver<T> {
    /// 消费 self：只能接收一次。
    pub fn recv(self) -> T {
        let mut guard = self.0.lock.0.lock().unwrap();
        while guard.val.is_none() {
            guard = self.0.lock.1.wait(guard).unwrap();
        }
        guard.val.take().unwrap()
    }
}
```

